import numpy as np
import pandas as pd

def model(regime, n, seed):
    T = 1.0
    if "T" in regime.config:
        T = float(regime.config["T"])
    rng = np.random.default_rng(seed)
    y = rng.normal(92.0 - 2.0 * (T - 1.0), 2.0, n)
    return pd.DataFrame({"unit_id": np.arange(n, dtype=int), "y": y})
